import base64, json, os, runpy, shutil, subprocess, sys, time
from pathlib import Path
os.environ.update(HF_HUB_DISABLE_XET="1", HF_HUB_DISABLE_PROGRESS_BARS="1", HF_HOME="/tmp/e52-hf",
                  OMP_NUM_THREADS="2", VLLM_WORKER_MULTIPROC_METHOD="spawn")
started = time.time()
out = Path("/kaggle/working/e62v-qwen-f")
out.mkdir(parents=True, exist_ok=True)
subprocess.run(["nvidia-smi"], check=True)
root = Path("/tmp/aimo-e52")
for name, encoded in json.loads('{"datagen/perturb/sample.py": "", "datagen/perturb/answers.py": "", "datagen/tokenizer_check.py": "", "datagen/extract_features.py": "", "scripts/kaggle_cuda_setup.py": "", "scripts/kaggle_process_guard.py": "", "data/e62/pool.parquet": "", "data/e62/variants.parquet": "", "protocols/E62_PROTOCOL.md": "", "e62_base/records.jsonl": ""}').items():
    dest = root / name
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_bytes(base64.b64decode(encoded))
cuda = runpy.run_path(str(root / "scripts/kaggle_cuda_setup.py"))["prepare_cuda_linker"]()
(out / "cuda-link-check.json").write_text(json.dumps(cuda, indent=2))
subprocess.run([sys.executable, "-m", "venv", "--without-pip", "/tmp/e52-env"], check=True)
py = "/tmp/e52-env/bin/python"
subprocess.run([sys.executable, "-m", "pip", "--python", py, "install", "--no-cache-dir", "-q", "vllm==0.20.0",
               "transformers==5.13.0", "huggingface-hub==1.22.0", "pandas==3.0.3", "pyarrow==24.0.0"], check=True)
freeze = subprocess.run([sys.executable, "-m", "pip", "--python", py, "freeze"], capture_output=True, text=True, check=True)
(out / "environment.txt").write_text(freeze.stdout)
guard = runpy.run_path(str(root / "scripts/kaggle_process_guard.py"))["run_guarded"]
if (root / "resume").is_dir():
    shutil.copytree(root / "resume", out, dirs_exist_ok=True)
phases = {'variants': ['datagen/perturb/sample.py', '--model-id', 'Qwen/Qwen3.5-4B', '--backend', 'vllm', '--pool', 'data/e62/pool.parquet', '--variants', 'data/e62/variants.parquet', '--k', '4', '--temperature', '1.0', '--top-p', '0.95', '--top-k', '40', '--max-new-tokens', '65536', '--tensor-parallel', '1', '--text-only', '--max-num-seqs', '64', '--chunk', '4', '--allow-no-solution', '--max-new-tokens', '32768', '--chunk', '16', '--out-dir', '/kaggle/working/e62v-qwen-f', '--problem-keys', '0380ceb3df411483', '08959a09ff8e8c46', '0ba153a240bc560c', '0f77dfc2934c7de5', '132733faabc475b0', '18db143d07901338', '1cc3b5951d1e11c0', '1f27596d6c9ed1a3', '21664e8724631d8e', '251581683cbb6ae0', '2b2bcc2edc21beec', '2f2f0e25ea3329e6', '324b4ed6f7296390', '34c6eb57a6af58d8', '38fee5cf07bfcec8', '3ad4909e3586f1fc', '3c80ea03ba835e03', '3dcba974b7a55f56', '418cd2130291e730', '44a564d85933077e', '46fb96aa6d13973b', '4dfd5aa3057a3545', '52ee50c9463b25ef', '5a0cab27bd0422fa', '5c6de279e35c1413', '620c056251098197', '659125a01c0f468f', '6be9da14643f7f47', '6f33b85ab278895b', '7516827df34c6acd', '79a1420da74a1e6e', '7cca6e4f169ad727', '8003b89032be9769', '835314e957f2141a', '87bd1144f542f385', '8e2d5bd493079b6d', '921983dd11591226', '97e44175f0b4e24c', '9b4166aa9428dfdc', '9d85cc5f5e8d793a', 'a2a8c5ba9789d1e9', 'a857943d4f72afad', 'ac981dd99792de58', 'b00c213f22c17b54', 'b469d2bec77c578e', 'b9bf4f5b4d4882ef', 'bd94290895307a9c', 'c06955ade64d1c1b', 'c4f14cd29d836d6f', 'cc00c000140b92e4', 'd0656a7b95265386', 'd542b3458a026339', 'da49d866adb77e8f', 'dd67243244d152bf', 'e21d219eda5b5cd9', 'e7205b728edb3646', 'eadf4b95241b8c82', 'ec442a3a3febd069', 'f0a640bfc633e02f', 'f49a0c498a8cae7f', 'f8b47ec25d8ef0ff', 'fce6845da74cd069', '--phase', 'variants', '--max-hours', '9.0', '--base-records', '/tmp/aimo-e52/e62_base/records.jsonl']}
results = {}
for phase, argv in phases.items():
    if True:
        # One engine per T4 (E24's layout for Qwen3.5-4B), each on half of this kernel's items.
        launcher = ("import os, subprocess, sys\n"
                    f"argv = {argv!r}\n"
                    "procs = [subprocess.Popen([sys.argv[1], *argv, '--num-shards', '2', '--shard-index', str(i)],\n"
                    "         env={**os.environ, 'CUDA_VISIBLE_DEVICES': str(i)}) for i in (0, 1)]\n"
                    "sys.exit(max(p.wait() for p in procs))")
        cmd = [py, "-c", launcher, py]
    else:
        cmd = [py, *argv]
    results[phase] = guard(cmd, root, out / f"{phase}.log", timeout=34200.0
                           if phase == "variants" else 34200.0)
    (out / "execution.json").write_text(json.dumps({**results, "end_to_end_seconds": time.time() - started}, indent=2))
raise SystemExit(max(r["exit_code"] for r in results.values()))
